sys_variable_value.value:
(function execute(inputs, outputs) {
    try {
        // Step 0: Look up the import request record to get parameters
        var reqGr = new GlideRecord('x_1775706_salesfor_sf_import_req');
        if (!reqGr.get(inputs.requestSysId)) {
            outputs.success = false;
            outputs.errorMessage = 'Import request record not found: ' + inputs.requestSysId;
            outputs.accountsImported = 0;
            outputs.contactsImported = 0;
            return;
        }

        var account = reqGr.getValue('account_name') || '';
        var includeContacts = reqGr.getValue('include_contacts') == '1' || reqGr.getValue('include_contacts') == 'true';

        // Step 1: Call SFDC REST API
        var r = new sn_ws.RESTMessageV2('SFDC Migration - Salesforce API', 'SFDC Migration - Get API Test');
        var endpoint = r.getEndpoint();
        endpoint += '?account=' + encodeURIComponent(account) + '&includeContacts=' + encodeURIComponent(includeContacts);
        r.setEndpoint(endpoint);

        var response = r.execute();
        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();

        // Step 2: Parse JSON response
        var data = JSON.parse(responseBody);

        if (data.status !== 'success') {
            outputs.success = false;
            outputs.errorMessage = 'API returned status: ' + (data.status || 'unknown') + '. HTTP: ' + httpStatus;
            outputs.accountsImported = 0;
            outputs.contactsImported = 0;
            return;
        }

        var accounts = data.accounts || [];
        var accountCount = 0;
        var contactCount = 0;

        // Step 3: Create import set for accounts
        var acctImportSet = new GlideRecord('sys_import_set');
        acctImportSet.initialize();
        acctImportSet.setValue('table_name', 'x_1775706_salesfor_sf_acct_stg');
        acctImportSet.setValue('state', 'loaded');
        var acctImportSetId = acctImportSet.insert();

        // Step 4: Insert account staging rows
        for (var i = 0; i < accounts.length; i++) {
            var acctData = accounts[i].account;
            if (acctData) {
                var stgRow = new GlideRecord('x_1775706_salesfor_sf_acct_stg');
                stgRow.initialize();
                stgRow.setValue('sys_import_set', acctImportSetId);
                stgRow.setValue('sys_import_state', 'pending');
                for (var key in acctData) {
                    if (acctData.hasOwnProperty(key) && acctData[key] !== null) {
                        stgRow.setValue('u_' + key.toLowerCase(), acctData[key]);
                    }
                }
                stgRow.insert();
                accountCount++;
            }
        }

        // Step 5: Run account transform
        var acctIsGr = new GlideRecord('sys_import_set');
        acctIsGr.get(acctImportSetId);
        var acctTransformer = new GlideImportSetTransformer();
        acctTransformer.transformAllMaps(acctIsGr);

        // Step 6: Import contacts if requested
        if (includeContacts) {
            var ctctImportSet = new GlideRecord('sys_import_set');
            ctctImportSet.initialize();
            ctctImportSet.setValue('table_name', 'x_1775706_salesfor_sf_ctct_stg');
            ctctImportSet.setValue('state', 'loaded');
            var ctctImportSetId = ctctImportSet.insert();

            for (var j = 0; j < accounts.length; j++) {
                var contacts = accounts[j].contacts || [];
                for (var k = 0; k < contacts.length; k++) {
                    var ctctData = contacts[k];
                    var ctctRow = new GlideRecord('x_1775706_salesfor_sf_ctct_stg');
                    ctctRow.initialize();
                    ctctRow.setValue('sys_import_set', ctctImportSetId);
                    ctctRow.setValue('sys_import_state', 'pending');
                    for (var cKey in ctctData) {
                        if (ctctData.hasOwnProperty(cKey) && ctctData[cKey] !== null) {
                            ctctRow.setValue('u_' + cKey.toLowerCase(), ctctData[cKey]);
                        }
                    }
                    ctctRow.insert();
                    contactCount++;
                }
            }

            // Step 7: Run contact transform
            var ctctIsGr = new GlideRecord('sys_import_set');
            ctctIsGr.get(ctctImportSetId);
            var ctctTransformer = new GlideImportSetTransformer();
            ctctTransformer.transformAllMaps(ctctIsGr);
        }

        // Step 8: Set output variables
        outputs.success = true;
        outputs.accountsImported = accountCount;
        outputs.contactsImported = contactCount;
        outputs.errorMessage = '';

    } catch (ex) {
        outputs.success = false;
        outputs.errorMessage = 'Error: ' + ex.message;
        outputs.accountsImported = 0;
        outputs.contactsImported = 0;
    }
})(inputs, outputs);

